import networkx as nx
import numpy as np

G = nx.Graph()
G.add_nodes_from(range(8))

# Add edges to satisfy minimum and maximum degree constraints
for i in range(8):
    for j in range(i+1, 8):
        if len(list(G.neighbors(i))) < 3 and len(list(G.neighbors(j))) < 3:
            G.add_edge(i, j)

# Add edges to satisfy edge count constraint
while G.number_of_edges() < 16:
    i = np.random.randint(0, 8)
    j = np.random.randint(i+1, 8)
    if not G.has_edge(i, j):
        G.add_edge(i, j)

# Check chromatic number constraint
if nx.algorithms.coloring.greedy_color(G) <= 2 and nx.algorithms.coloring.greedy_color(G) >= 2:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
